\u007c\u0079\u0051\u0022\u0062\u0024\u0060\u005b\u0056\u0038\u0048\u0032\u006b\u0066\u0061\u0079\u002b\u002c\u0029\u0035\u0075\u0065\u0068\u0077\u002a\u003d\u0071\u0061\u0037\u0028\u0072\u005f\u0034\u0077\u0039\u006f\u0038\u0046\u0078\u0050\u002e\u0025\u007b\u0072\u0061\u0060\u0072\u002b\u002b\u007e\u0042\u0028\u0053\u0068\u0042\u0058\u0073\u007c\u0071\u002c\u0041\u0069\u0021\u0032\u0051\u0077\u004f\u0060\u006e\u0024\u003e\u0046\u0057\u007c\u0063\u004e\u0025\u004f\u0024\u003e\u003e\u0074\u0034\u0028\u0076\u005f\u0034\u0067\u006f\u0049\u004f\u0079\u0038\u007a\u004a\u0068\u007b\u002e\u0056\u0078\u006f\u006d\u0030\u0077\u0071\u0049\u0071\u003a\u005b\u005b\u0069\u0079\u006b\u005e\u005e\u0045\u006a\u0074\u007d\u0031\u004b\u004d\u0049\u0071\u0045\u004d\u005e\u0046\u0033\u006b\u0060\u006c\u003a\u0050\u0026\u0078\u0079\u004c\u0035\u0058\u005d\u0032\u0063\u003a\u007b\u002a\u0048\u004e\u0024\u0079\u0063\u003d\u006b\u0046\u005b\u0028\u0067\u0077\u0021\u0054\u0050\u0060\u003a\u002a\u0036\u002f\u0069\u0074\u006b\u002f\u0025\u0024\u0065\u0039\u006c\u0022\u004b\u0023\u0066\u0065\u0069\u002b\u0057\u007e\u0057\u002e\u0079\u006a\u006a\u0030\u0060\u003a\u0039\u0037\u006d\u0078\u006c\u0022\u004b\u0023\u0066\u0065\u0069\u002b\u0057\u007e\u0057\u002e\u0079\u006a\u006a\u0030\u0060\u003a\u0039\u0037\u006d\u0078\u006c\u0022\u004b\u0023\u0066\u0065\u0069\u002b\u0057\u007e\u0057\u002e\u0079\u006a\u006a\u0030\u0060\u003a\u0039\u0037\u006d\u0078\u006c\u0022\u004b\u0023\u0066\u0065\u0069\u0052\u0045\u004a\u003b\u0067\u0065\u0026\u003a\u0034\u004a\u0055\u004f\u007c\u0024\u0025\u007c\u0068\u004e\u0038\u005b\u0067\u0049\u0062\u0042\u0073\u002f\u0033\u0054\u0029\u0033\u0063\u003d\u006f\u0045\u0021\u0074\u0057\u003b\u0073\u005d\u0060\u0074\u0047\u0054\u006f\u004a\u0065\u0049\u002f\u007a\u002e\u0071\u004e\u003d\u004d\u003b\u0079\u006b\u0060\u0066\u0043\u0061\u0049\u0057\u0032\u004b\u0025\u0022\u0026\u0069\u002c\u0047\u004d\u0034\u002e\u002e\u0022\u006f\u002a\u0038\u005d\u0056\u0056\u006b\u0059\u0026\u0041\u0033\u0031\u007e\u006c\u007e\u0067\u0057\u007a\u0041\u0032\u0043\u0061\u0049\u0056\u0029\u004a\u007d\u006e\u005d\u0051\u0022\u002a\u005b\u0062\u0036\u007c\u0025\u005f\u004e\u0057\u0065\u006f\u0053\u005d\u007e\u0056\u0029\u004a\u007d\u006e\u005d\u0051\u0022\u002a\u005b\u0062\u0036\u007c\u0025\u005f\u004e\u0057\u0065\u006f\u0053\u005d\u007e\u0056\u0029\u004a\u007d\u006e\u005d\u0051\u0022\u002a\u005b\u0062\u0036\u007c\u0025\u005f\u004e\u0057\u0065\u006f\u0053\u005d\u007e\u0056\u0029\u004a\u007d\u006e\u005d\u0031\u006d\u006f\u0050\u004e\u002f\u0029\u0073\u005b\u0074\u0038\u005d\u0079\u0045\u0023\u006b\u0054\u0070\u003f\u0064\u0067\u0026\u002b\u0035\u006f\u005b\u004d\u0034\u002e\u0077\u004b\u0045\u0044\u0053\u0028\u0032\u003a\u007a\u006c\u006f\u0076\u0041\u007b\u004f\u0062\u004b\u004f\u006f\u0051\u0069\u0061\u0049\u0070\u003b\u0022\u0045\u004c\u0075\u0071\u007e\u0062\u0077\u007d\u0052\u0054\u0042\u005d\u0047\u006b\u005e\u003a\u0031\u006e\u0074\u0065\u0077\u0057\u0051\u0074\u0049\u0062\u004f\u007c\u004f\u007a\u0024\u0071\u006f\u004a\u0037\u0046\u006d\u003b\u007a\u0063\u0030\u005b\u0045\u0078\u0064\u0043\u005e\u0036\u003a\u0044\u0075\u006d\u0028\u006b\u0059\u0038\u007a\u0022\u0024\u007a\u006c\u0065\u0070\u0032\u007c\u004c\u0047\u0051\u003e\u0035\u0073\u004f\u0031\u0077\u003c\u007e\u0041\u0065\u0046\u005b\u0035\u0035\u0043\u007c\u007e\u0067\u0064\u006a\u007a\u0024\u0044\u0034\u005d\u0053\u0046\u0026\u0051\u006f\u002c\u007d\u0047\u0056\u006a\u0076\u0024\u0062\u003b\u005d\u003e\u007a\u0059\u002a\u006c\u007b\u0060\u0069\u0037\u0036\u0056\u004e\u0033\u0052\u007a\u006f\u0046\u0076\u0074\u005a\u005e\u0060\u006b\u003b\u004b\u003b\u005d\u0023\u0031\u003c\u0044\u005b\u0047\u003c\u0037\u0063\u003d\u003f\u007b\u0040\u005a\u0036\u0028\u0047\u0023\u0029\u0052\u0031\u004f\u006c\u0059\u0064\u006f\u0057\u007b\u007b\u0032\u002e\u0028\u007a\u0051\u006b\u0029\u004d\u0022\u006f\u0071\u0037\u006f\u0050\u0023\u0032\u006c\u0034\u0068\u004b\u0046\u0038\u0078\u005a\u004f\u005d\u0076\u003f\u0045\u0066\u0039\u0038\u006b\u0054\u0070\u0035\u0055\u005b\u002a\u0071\u0076\u0067\u004b\u0055\u0026\u0065\u002e\u0071\u0028\u006a\u0025\u0034\u0069\u002c\u0024\u002e\u0064\u0078\u0072\u0061\u003c\u0024\u0069\u0077\u007c\u0065\u0062\u0033\u0067\u007c\u0048\u0078\u0034\u0039\u003e\u0036\u005d\u0071\u0024\u0039\u003b\u007d\u0067\u0067\u0033\u0024\u005b\u0065\u0030\u0044\u0070\u0070\u004a\u002c\u005b\u005d\u0042\u0069\u006c\u0069\u0051\u007d\u006e\u0070\u005e\u0050\u003e\u0077\u0054\u003b\u0069\u007e\u005a\u0066\u0073\u0064\u0053\u002b\u0058\u005b\u0051\u004a\u006e\u0033\u006b\u003f\u0066\u0073\u002e\u0068\u0040\u0042\u0067\u004a\u003a\u0058\u003b\u007c\u0060\u006c\u007b\u0029\u0033\u002e\u0039\u0077\u003b\u003a\u002e\u004c\u0047\u006d\u0041\u0051\u0039\u0025\u003f\u003c\u0070\u0051\u0021\u002f\u0052\u0033\u0053\u0021\u0065\u0069\u0058\u0029\u0064\u0040\u0030\u0064\u002c\u007a\u0045\u0046\u0024\u003b\u0038\u004d\u0026\u0047\u0070\u007d\u0068\u005f\u0021\u006f\u0023\u0059\u0045\u0045\u005d\u0079\u0038\u0051\u0048\u006c\u0047\u0065\u002e\u0023\u006b\u0037\u005e\u005a\u0049\u0024\u006a\u003d\u002a\u0021\u006f\u005e\u005d\u0041\u002e\u0031\u0030\u003f\u003d\u0071\u0024\u0065\u0037\u0061\u0075\u0072\u003a\u0063\u0071\u006d\u0022\u0033\u0052\u0044\u0021\u0064\u002c\u0077\u004d\u0065\u004f\u005f\u0021\u006f\u002b\u0032\u0043\u005d\u005f\u0062\u0052\u002a\u0047\u0069\u006c\u0045\u0040\u0041\u002b\u0059\u002f\u0031\u006c\u0060\u0064\u006a\u0058\u0033\u0065\u005f\u002f\u0033\u0038\u0045\u0045\u0051\u005f\u0023\u0044\u003b\u0057\u006c\u0071\u0060\u003d\u0056\u0061\u0023\u0060\u007e\u0062\u003f\u0062\u0053\u0057\u0050\u0074\u0049\u007c\u0039\u0023\u004e\u0054\u0030\u006f\u002b\u006d\u0036\u0054\u0053\u006f\u0055\u004a\u0037\u0021\u0025\u0023\u003f\u005e\u005b\u0053\u0049\u0047\u003f\u002b\u0071\u0030\u003b\u006b\u003c\u006d\u0022\u005e\u0066\u002b\u003e\u0069\u0070\u0073\u006a\u004d\u005a\u0077\u0023\u0022\u004e\u002e\u005d\u0033\u0076\u0046\u0079\u0047\u0059\u0053\u007a\u003c\u003f\u007e\u0050\u006a\u003f\u0026\u006e\u002b\u0022\u0053\u0039\u0052\u002b\u0045\u0030\u0077\u004f\u002b\u007b\u005e\u003d\u0048\u0039\u002a\u0074\u0038\u006a\u002a\u004f\u003d\u003a\u007d\u0055\u0052\u004a\u003c\u003e\u0075\u0061\u007a\u0049\u005b\u002a\u007e\u007d\u006a\u0034\u0043\u003e\u0033\u0049\u0065\u0038\u0032\u002a\u0042\u0046\u007d\u0057\u0066\u0044\u0078\u0045\u0072\u0068\u0048\u006d\u0072\u0079\u0052\u006d\u0056\u0075\u006a\u002c\u007e\u003c\u0060\u004d\u0053\u0024\u0079\u0034\u0075\u0068\u002e\u004e\u004b\u0058\u003d\u006a\u0051\u0062\u006f\u0059\u0072\u0054\u0066\u004d\u0053\u007a\u004e\u006d\u0076\u0031\u0047\u0063\u002a\u004c\u006f\u0057\u0041\u003b\u0047\u0042\u0040\u0048\u002c\u003d\u004f\u0025\u003e\u0076\u003f\u0075\u0065\u0030\u0036\u0058\u0079\u0052\u003c\u0036\u004f\u0070\u002e\u007e\u0049\u002c\u007d\u0032\u0021\u007d\u0061\u0064\u0070\u006a\u0045\u0058\u0063\u0046\u005a\u005b\u0033\u003c\u002a\u006a\u004d\u0073\u0025\u0060\u0033\u003e\u0068\u005a\u0033\u0056\u0066\u0051\u0046\u0021\u003d\u006e\u006d\u0023\u0026\u0053\u006e\u0061\u0025\u0021\u0029\u0065\u005a\u0040\u0039\u0031\u004a\u0078\u0035\u005e\u0072\u004e\u0056\u007a\u0045\u004e\u004d\u007b\u0067\u0040\u0040\u005a\u0024\u0074\u0074\u003b\u0067\u0061\u002a\u0072\u0054\u0048\u0066\u007b\u0024\u005e\u0039\u0032\u005d\u0023\u0065\u0077\u0047\u0040\u006b\u0072\u003c\u004d\u0062\u0026\u007d\u006b\u0034\u0032\u003f\u0058\u0032\u0067\u004b\u0073\u0040\u0052\u0067\u0029\u0065\u007b\u0053\u0061\u0024\u0029\u0034\u004e\u0024\u004a\u003e\u007b\u0049\u0053\u006e\u0059\u006e\u0033\u006c\u0061\u0044\u007d\u007b\u0043\u003f\u0021\u0032\u0078\u0038\u0075\u003f\u0047\u002c\u0032\u004e\u002b\u006b\u004d\u003f\u0021\u0032\u0078\u0038\u0075\u0025\u0057\u0032\u0057\u0024\u004f\u003c\u006d\u0075\u004a\u005b\u0037\u0043\u0066\u007a\u0033\u0038\u006a\u0068\u0056\u0078\u007e\u0041\u0056\u004b\u0044\u0037\u0045\u0049\u002c\u002e\u0038\u0026\u0068\u0074\u0063\u003d\u0023\u002a\u003c\u0021\u0077\u0030\u004e\u0038\u006f\u005e\u0031\u003b\u0070\u0030\u0031\u0025\u006e\u0030\u0066\u0076\u006c\u0064\u0023\u003d\u007d\u002c\u004d\u005a\u007d\u005d\u0050\u003b\u0031\u0038\u006e\u006c\u0074\u003b\u006b\u0045\u0028\u006e\u0029\u006a\u0064\u0044\u0038\u0051\u005b\u0079\u002b\u0069\u0069\u0050\u0043\u0046\u0057\u0022\u0053\u005d\u0047\u002f\u006c\u0056\u0051\u003c\u006d\u006f\u0056\u0058\u0040\u0034\u004c\u0024\u0045\u0032\u002f\u0052\u0057\u0043\u006c\u0052\u0031\u004b\u0029\u0022\u0044\u004b\u0056\u0026\u0024\u0058\u003d\u0023\u0079\u0045\u003d\u0038\u005e\u0043\u002c\u006a\u0037\u0051\u0077\u005a\u0042\u0061\u006b\u0055\u0048\u0044\u0070\u0050\u0070\u0057\u0040\u007d\u003f\u004c\u0054\u003e\u0033\u006c\u003a\u0051\u002f\u007c\u0033\u0037\u004d\u0072\u0023\u003b\u005a\u005a\u003c\u0046\u0072\u0060\u0052\u006a\u005a\u007a\u0066\u0054\u005e\u0075\u006a\u0028\u0072\u0061\u0047\u0025\u006e\u0041\u003b\u0037\u0055\u005d\u0079\u0065\u0046\u003b\u007c\u002b\u0077\u0049\u0037\u0076\u0074\u0071\u0031\u0026\u0022\u005d\u006d\u0075\u0041\u004b\u0073\u006f\u0047\u0022\u0041\u005a\u006b\u007e\u0076\u005e\u003a\u007b\u0030\u002a\u0034\u003e\u0035\u004d\u002f\u004e\u0076\u0063\u0078\u0053\u004b\u0041\u0060\u0065\u002a\u0061\u0021\u003e\u005f\u004b\u0069\u0043\u0057\u0036\u0069\u004c\u0075\u002e\u006d\u0065\u0077\u0024\u004c\u0029\u0076\u004b\u0049\u0043\u0037\u0071\u0058\u006a\u0025\u0067\u003a\u007b\u0061\u0038\u0062\u0061\u0024\u007c\u0039\u0075\u0057\u0036\u0076\u006a\u0040\u0041\u0055\u0036\u0032\u0059\u0075\u0047\u0073\u0079\u0079\u0035\u006c\u0052\u0077\u0042\u0033\u0021\u0047\u0022\u0051\u003c\u004b\u002b\u0055\u0075\u004d\u0025\u006d\u0058\u0050\u0023\u0060\u0023\u005e\u0024\u0032\u004f\u006d\u0068\u0060\u0057\u007a\u005d\u0021\u002b\u006d\u0060\u0071\u0059\u0031\u0032\u0059\u0030\u0066\u0076\u004b\u0066\u0079\u004c\u0071\u004a\u0043\u0062\u0078\u004a\u0040\u0032\u0059\u0030\u0033\u0030\u0029\u0057\u0033\u002e\u006a\u0058\u0044\u0051\u0062\u0025\u0060\u0063\u006e\u0022\u006c\u002c\u0031\u0030\u0026\u0033\u0036\u0031\u0054\u0044\u0054\u003a\u007a\u003c\u0036\u0025\u0049\u0032\u0071\u0056\u007a\u0053\u0045\u0028\u0078\u0055\u006d\u0021\u006c\u004e\u0043\u002b\u0047\u0074\u005e\u0037\u0042\u002b\u006e\u0036\u0025\u005f\u005d\u006f\u0045\u004d\u0066\u0025\u003b\u004b\u0073\u006f\u003a\u0031\u0065\u006b\u0031\u003a\u0046\u0030\u0041\u0059\u0065\u0054\u005a\u005d\u006e\u007a\u006b\u0046\u0035\u0066\u005d\u003f\u0059\u0035\u006e\u0059\u0033\u0031\u006a\u0023\u0048\u006b\u0060\u0079\u0075\u0050\u003b\u0025\u003b\u003c\u0037\u0063\u003d\u003f\u007b\u0040\u005a\u0036\u0028\u0047\u0023\u0032\u0042\u006b\u002e\u0078\u005d\u0078\u006f\u0069\u0043\u002a\u0053\u0058\u0070\u0035\u002b\u0073\u007d\u0026\u005f\u006e\u0059\u0056\u0030\u0061\u0052\u0078\u003f\u0024\u006c\u0035\u007c\u005d\u0057\u0036\u004c\u0023\u0064\u002e\u0034\u0059\u0076\u003f\u005d\u0043\u0076\u0059\u0063\u003d\u0066\u0043\u002c\u0058\u0075\u0069\u0040\u0055\u0042\u0065\u0073\u005a\u0023\u006d\u0023\u0063\u0037\u0046\u0057\u0079\u0044\u0058\u0060\u007c\u0065\u003d\u0043\u0046\u006a\u0041\u0043\u0022\u003b\u002b\u0068\u0035\u006a\u0022\u0039\u0071\u0072\u005b\u005f\u0061\u0072\u007b\u0065\u006d\u0032\u0071\u0039\u003d\u0028\u003b\u0074\u0047\u003a\u0073\u0065\u005a\u006c\u0066\u006b\u002e\u0063\u005e\u0035\u002a\u0032\u005f\u0068\u0047\u0041\u005f\u003e\u0060\u0071\u0074\u005f\u0061\u0026\u006a\u006e\u005e\u0041\u0054\u005a\u004f\u0038\u0043\u0066\u002c\u004d\u0048\u005d\u0042\u002c\u0071\u006a\u0071\u0037\u004e\u0079\u0029\u0030\u003a\u0078\u0076\u0040\u0055\u003f\u002c\u003a\u0048\u006c\u0034\u007a\u0066\u003e\u0047\u003d\u007b\u0028\u007d\u0026\u002b\u0048\u0042\u0064\u0077\u0049\u0046\u004e\u0022\u004a\u0026\u002f\u005d\u006a\u002e\u0077\u0066\u0048\u0072\u0069\u003e\u0035\u006c\u0051\u0021\u003d\u004e\u0032\u004a\u0025\u0063\u0066\u0038\u004b\u004c\u0043\u0028\u0025\u0023\u0058\u0040\u0050\u0026\u004c\u005b\u006b\u0044\u0045\u0064\u0075\u0054\u006b\u007b\u0067\u005d\u003b\u0051\u0049\u0058\u005b